import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address whale;

    function setUp() public {
        whale = address(0x1234);
        c = new C(whale, 0);
    }

    function testFuzz_property(uint256 newBetLimit, uint256 donateAmount) public {
