pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint256).max);
        vm.prank(address(0x1)); // not the owner, will revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", amount));
        // On the reference contract, only owner can call AdjustBetAmounts; non-owner call reverts.
        // On the mutated contract, the onlyRealPeople modifier uses msg.sender != tx.origin,
        // so a direct EOA call (msg.sender == tx.origin) fails the require, causing revert.
        // In both cases, the call reverts; the property is that after a failed call,
        // currentBetLimit() remains unchanged (default 0).
        assertTrue(!success || c.currentBetLimit() == amount);
    }
}

