pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 wagerLimit) public {
        // ensure the wager limit is reasonable (non-zero and less than balance)
        vm.assume(wagerLimit > 0 && wagerLimit < address(c).balance);

        // fund the contract so it can play
        vm.deal(address(c), 10 ether);

        // open to public
        c.OpenToThePublic();

        // adjust bet limit
        c.AdjustBetAmounts(wagerLimit);

        // prepare a player who will wager and lose
        address player = address(0x1234);
        vm.deal(player, wagerLimit);
        vm.prank(player);
        c.wager{value: wagerLimit}();

        // record winnersPot before playing
        uint256 potBefore = c.winnersPot();

        // player plays, will lose (since we mine a block to make blockNumber < block.number)
        vm.roll(block.number + 1);
        vm.prank(player);
        c.play();

        // check: winnersPot after loss should be less than before (half of balance is sent to whale)
        uint256 potAfter = c.winnersPot();

        // In the reference, losing sends betLimit/2 to whale, so balance decreases by betLimit/2, thus winnersPot = (balance - betLimit/2)/2 which is less than old balance/2 if betLimit > 0
        // In the bug, loss also pays out half of balance to the player, which could increase or decrease pot depending, but often it doesn't preserve the property that potAfter < potBefore for all cases.
        // The general rule: after playing a losing round, the winnersPot must be strictly smaller than before (since some ether leaves the contract).
        assertTrue(potAfter < potBefore);
    }
}

