pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        // bound to a reasonable range
        newBetLimit = bound(newBetLimit, 1, 1000 ether);

        // Record balance before AdjustBetAmounts
        uint256 balanceBefore = address(c).balance;

        // Call AdjustBetAmounts
        c.AdjustBetAmounts(newBetLimit);

        // The rule: the contract's ether balance after the call is >= half of what it was before
        // This holds for the reference because AdjustBetAmounts only changes a state variable, not the balance.
        // For the mutant, the play() branch loses both ways, potentially reducing balance further, but this call itself should not change balance.
        // Actually, since the mutation is in play(), not AdjustBetAmounts, the rule should capture a post-condition of AdjustBetAmounts that the mutant violates indirectly.
        // However, AdjustBetAmounts does not change balance in either version, so the rule holds for both. We need a rule that the reference satisfies and the mutant breaks.
        // The correct rule: After AdjustBetAmounts, the contract's totalDonated equals (address(this).balance before - address(this).balance after) * 2 if a play happened.
        // But since AdjustBetAmounts doesn't trigger play, we need a different approach.
        // Let's re-read the difference: the mutant changes play() so both branches lose. The property should involve play().
        // But the instruction says to drive through public surface ending with AdjustBetAmounts. So we should call wager() and play() before AdjustBetAmounts to set up state.
        // Let me redesign:
        vm.deal(address(this), 10 ether);
        c.OpenToThePublic();
        c.AdjustBetAmounts(1 ether);
        c.wager{value: 1 ether}();

        // Record balance before play
        uint256 balanceBeforePlay = address(c).balance;

