pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(address player, uint256 betLimit, uint256 diff) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(betLimit > 0 && betLimit <= 1e24);
        vm.assume(diff >= 2 && diff <= 1000);

        // Open to public and set difficulty
        c.OpenToThePublic();
        c.AdjustDifficulty(diff);
        c.AdjustBetAmounts(betLimit);

        // Player must have enough balance to wager
        vm.deal(player, betLimit);

        // Record initial totalDonated via public getter (if exists) - but totalDonated is private, so we use balance trick
        uint256 balanceBefore = address(c).balance;

        // Player wagers
        vm.prank(player);
        c.wager{value: betLimit}();

        // Player plays (will lose because random seed is 0, and blockhash(blocknumber) is deterministic)
        // Force a loss: we need winningNumber != difficulty/2
        // Since blockhash and keccak are deterministic, we can ensure loss by setting difficulty such that
        // winningNumber != difficulty/2. We'll just play and check behavior.
        vm.roll(block.number + 1);
        vm.prank(player);
        c.play();

        // Call AdjustBetAmounts again to check invariant
        uint256 balanceMid = address(c).balance;
        c.AdjustBetAmounts(betLimit / 2);
        uint256 balanceAfter = address(c).balance;

        // In the reference, on loss, loseWager(betLimit/2) sends betLimit/2 to whale, reducing contract balance
        // In the buggy version, loseWager(0) sends nothing
        // So after AdjustBetAmounts (which doesn't change balance), the decrease in balance from play
        // should be betLimit/2 in reference, but 0 in buggy
        // Since we cannot read totalDonated directly, we use balance change
        // The total balance decrease from before wager to after play+AdjustBetAmounts:
        // In reference: decrease = betLimit (wager) - lost_amount = betLimit - (betLimit/2) = betLimit/2 (actually wager stays, then lose sends half betLimit out, so net: +betLimit from wager, -betLimit/2 from loss = +betLimit/2; but balance after play = balanceBefore + betLimit - betLimit/2)
        // Actually careful: Before wager balance = balanceBefore; after wager: balanceBefore + betLimit; after loss: balanceBefore + betLimit - betLimit/2; after AdjustBetAmounts (no balance change): same
        // So balanceAfter - balanceBefore should be betLimit/2 in reference, but in buggy it's betLimit (since no loss transfer)
        // So the property: balanceAfter - balanceBefore == betLimit - (betLimit/2) in reference
        uint256 diffBalance = balanceAfter - balanceBefore;
        assertTrue(diffBalance == betLimit / 2, "Balance difference should equal betLimit/2 in reference");
    }
}

