import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(this));
        vm.assume(player.code.length == 0); // ensure player is an EOA

        // Open to public
        c.OpenToThePublic();

        // Set a bet limit so wager can be placed
        uint256 betLimit = 1 ether;
        c.AdjustBetAmounts(betLimit);

        // Player wagers exactly betLimit
        vm.deal(player, betLimit);
        vm.prank(player);
        c.wager{value: betLimit}();

        // Now call AdjustBetAmounts again to satisfy the drive requirement
        c.AdjustBetAmounts(betLimit);

        // After a valid wager, hasPlayerWagered should return true
        // (Buggy version would return false because timestamps[player] is 0 after play() but wagers[player] > 0)
        // Actually, the bug makes hasPlayerWagered return timestamps[player] > 0, which after play() would be 0,
        // but before play() it would be block.number > 0 so both return true.
        // To break, we need to call play() to reset timestamps while wagers still > 0...
        // But the bug replaces wagers with timestamps. Let's test the case where timestamps is reset but wagers is not:
        // Actually the condition is: return timestamps[player] > 0; 
        // After play(), timestamps resets to 0 but wagers also resets to 0. So no difference.
        // The difference appears when a player has a timestamp but no wager? But constructor and functions ensure they're consistent.
        // The bug breaks the property that hasPlayerWagered returns only for those who have actually wagered.
        // Since both mappings are set together and cleared together, the only way to see a difference is if there is a path that sets timestamps without wagers? None exists.
        // Actually the bug is subtle: the reference uses wagers[player] > 0, the bug uses timestamps[player] > 0.
        // They behave identically for all valid sequences. So the assertion must be vacuous.
        // To force a difference, we need a scenario where timestamps > 0 but wagers == 0, which never occurs.
        // Thus the property "hasPlayerWagered returns true for player who wagered and false for others" holds in both.
        // Therefore I cannot write a distinguishing test. 
    }
}

