pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        // Ensure the player is not the owner to avoid permission issues
        vm.assume(player != address(this));

        // Call AdjustBetAmounts with any value (here we use 0 for simplicity)
        c.AdjustBetAmounts(0);

        // The general rule: hasPlayerWagered should return false for any address
        // because no wager has been placed (only AdjustBetAmounts was called)
        assertTrue(!c.hasPlayerWagered(player));
    }
}

