pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        // Ensure the player is not the owner and is a real person (tx.origin)
        vm.assume(player != address(this));
        // Call AdjustBetAmounts to satisfy the bug's entry point context
        c.AdjustBetAmounts(0);
        // General rule: hasPlayerWagered(player) must equal (c.wagers(player) > 0)
        bool hasWageredViaFunction = c.hasPlayerWagered(player);
        bool hasWageredViaMapping = c.wagers(player) > 0;
        assertTrue(hasWageredViaFunction == hasWageredViaMapping);
    }
}
